"""Refine long rows against transverse physical-cell widths within a Bundle.

Keep the original rows and transverse counts. Refine axial intervals using
their physical advance relative to the narrowest transverse cell, then rerun
the complete source-knot boundary certificate. This is a sizing heuristic;
final positive-cell, perimeter and allocation checks still decide acceptance.
The default measures separated bands; a supplied width callback also supports
conservative bounds for virtual mesh bands in mixed separator/overlap spans.
"""
from . import bundle_axis_nodes as axis, bundle_resample_nodes as resample


def construct(g, table, mandatory, length, query, side_count, middle_count, eligible, *, cell_widths=None):
    index=g.node('GeometryNodeInputIndex','Physical row balance interval').outputs[0]
    count=axis._size(g,table)
    interval=g.math('MINIMUM',index,g.math('SUBTRACT',count,2.))
    metric=g.named('st_bundle_metric','FLOAT')
    start=g.sample(table,metric,interval,'FLOAT')
    end=g.sample(table,metric,g.math('ADD',interval,1.),'FLOAT')
    first,last=query(start),query(end)
    widths=[]
    for points in (first,last):
        if cell_widths is None:
            for k,segments in enumerate((side_count,middle_count,side_count)):
                widths.append(g.math('DIVIDE',g.vector('DISTANCE',points[k],points[k+1]),segments))
        else:
            widths.extend(cell_widths(points))
    minimum=widths[0]
    for width in widths[1:]:minimum=g.math('MINIMUM',minimum,width)
    advance=g.vector('DISTANCE',first[0],last[0])
    for k in range(1,4):advance=g.math('MAXIMUM',advance,g.vector('DISTANCE',first[k],last[k]))
    ratio=g.math('DIVIDE',advance,g.math('MAXIMUM',minimum,1e-8))
    active=g.all(eligible,g.compare(g.stat(table,ratio,output='Max'),7.,'GREATER_THAN'))
    initial=g.math('MAXIMUM',1.,g.math('CEIL',g.math('DIVIDE',ratio,4.)))
    refined,_count,valid,_error=resample.construct(g,mandatory,length,1.,query,active,
        anchors=table,initial_segments=initial)
    result=g.switch(active,table,refined,'GEOMETRY','Balance long rows without moving physical boundaries')
    return result,g.either(g.boolean('NOT',active),valid)


def install_saved(original):
    """Apply the canonical refinement to a saved v4 experimental primitive."""
    from .path_surface_nodes import _Nodes
    from . import bundle_lookup_nodes
    if original.get('st_bundle_uniform_separated')!=4:
        raise ValueError('Expected the v4 uniform separated-Bundle primitive')
    tree=original.copy();tree.name=original.name.replace(' v4 /',' v5 /')
    g=_Nodes(tree)
    def named(label, kind=None):
        node,=[n for n in tree.nodes if n.label==label and (kind is None or n.type==kind)]
        return node
    def incoming(socket):
        value,=[link.from_socket for link in socket.links]
        return value
    counts=[]
    for label in ('Owner shoulder direct quads','Separator or merged crown direct quads'):
        addition=incoming(named(label).inputs['Vertices X']).node
        assert addition.bl_idname=='ShaderNodeMath' and addition.operation=='ADD'
        assert addition.inputs[1].default_value==1.
        counts.append(incoming(addition.inputs[0]))
    active=incoming(counts[0].node.inputs['Switch'])
    assert active==incoming(counts[1].node.inputs['Switch'])
    outer=named('st_bundle_outer_a','STORE_NAMED_ATTRIBUTE');table=incoming(outer.inputs['Geometry'])
    assert table.node.type=='STORE_NAMED_ATTRIBUTE' and table.node.inputs['Name'].default_value=='st_bundle_regular_rows'
    last=named('Final physical Bundle station')
    end,=[link.to_node for link in last.outputs['Mesh'].links if link.to_node.type=='STORE_NAMED_ATTRIBUTE'
          and link.to_node.inputs['Name'].default_value=='st_bundle_metric']
    length=incoming(end.inputs['Value'])
    lookups=[n for n in tree.nodes if n.type=='GROUP' and n.node_tree
             and n.node_tree.name=='Prochitecture Streets / Bundle boundary interpolation v1']
    curves=[incoming(lookups[0].inputs['Boundary '+str(k)]) for k in range(4)]
    assert all([incoming(n.inputs['Boundary '+str(k)]) for k in range(4)]==curves for n in lookups)
    mandatory=axis._join(g,*(incoming(named('Monotone boundary '+str(k)+' physical-axis lookup').inputs['Geometry'])
                            for k in range(4)))
    refined,valid=construct(g,table,mandatory,length,
        lambda s:bundle_lookup_nodes.evaluate(g,curves,s),*counts,active)
    bounded=named('Bound whole Bundle allocation before three quad grids')
    size=incoming(bounded.inputs['True']).node
    assert size.bl_idname=='GeometryNodeAttributeDomainSize' and incoming(size.inputs['Geometry'])==table
    budget=incoming(bounded.inputs['Switch']);destinations=[link.to_socket for link in budget.links]
    combined=g.all(budget,valid)
    for socket in destinations:g.set(combined,socket)
    g.set(refined,size.inputs['Geometry']);g.set(refined,outer.inputs['Geometry'])
    tree['st_bundle_uniform_separated']=5;tree['st_bundle_physical_row_balance']=1
    return tree
